class DFSAgent:
    def __init__(self, colors, adjacency):
        self.colors = colors
        self.adjacency = adjacency

    def valid_coloring(self, state, new_node=None):
        # state = {'A':'rosso', 'B':None}
        # -> state = {'A':'rosso'}
        # return all( 
        #   all( state[node] == state.get(neighbor, None) 
        #           for neighbor in self.adjacency[node]) 
        #   for node in state )
        nodes_to_check = state.keys()
        if new_node is not None:
            nodes_to_check = [new_node]
        for node in nodes_to_check:
        #state if not new_node else [new_node]:
            for neighbor in self.adjacency[node]:
                if state[node] == state.get(neighbor, None):
                    return False
        return True

    def next_states(self, state):
        for node in self.adjacency:
            if node not in state:
                #node = [n for n in self.adjacency if n not in state][0]
                #yield from (ns for c in self.colors if self.valid_coloring(ns:={**state, node:c}, new_node=node))
                for c in self.colors:
                    new_state = {**state, node:c}
                    if self.valid_coloring(new_state, new_node=node):
                        yield new_state
                break

    def dfs(self, state=None):
        if state==None:
            state = {}
        if len(state) == len(self.adjacency):
            yield state
        for next_state in self.next_states(state):
            yield from self.dfs(next_state)

from itertools import chain
class DFSAgentIterative(DFSAgent):
    def __init__(self, colors, adjacency):
        super().__init__(colors, adjacency)
        self.frontier = [{}]

    def dfs(self):
        while self.frontier:
            state = self.frontier.pop(0)
            if len(state) == len(self.adjacency):
                yield state
            self.frontier = list(self.next_states(state)) + self.frontier

class DFSAgentIterative2(DFSAgent):
    def __init__(self, colors, adjacency):
        super().__init__(colors, adjacency)
        self.frontier = [{}, None]

    def dfs(self):
        while (state := self.frontier.pop(0))!= None:
            if len(state) == len(self.adjacency):
                print(self.generated_states)
